+// Copyright (c) 2011 The Chromium Authors. All rights reserved.
+// Use of this source code is governed by a BSD-style license that can be
+// found in the LICENSE file.
+
+// TTS api test for Chrome on ChromeOS.
+// browser_tests.exe --gtest_filter="TtsApiTest.*"
+
+if (!chrome.tts) {
+  chrome.tts = chrome.experimental.tts;
+}
+
+if (!chrome.ttsEngine) {
+  chrome.ttsEngine = chrome.experimental.ttsEngine;
+}
+
+chrome.test.runTests([
+  function testTtsEngineError() {
+    // Register listeners for speech functions, but have speak return an
+    // error when it's used.
+    var speakListener = function(utterance, options, sendTtsEvent) {
+      chrome.test.assertEq('extension speech', utterance);
+
+      try {
+        // This should fail because 'foo' isn't a valid event type.
+        sendTtsEvent({'type': 'foo'});
+        chrome.test.fail();
+      } catch (e) {
+      }
+
+      // This won't actually send an event, and an error will be logged
+      // to the console, because we haven't registered the 'word'
+      // event type in our manifest.
+      sendTtsEvent({'type': 'word'});
+
+      // This will succeed.
+      sendTtsEvent({
+        'type': 'error',
+        'charIndex': 0,
+        'errorMessage': 'extension tts error'});
+    };
+    var stopListener = function() {};
+    chrome.ttsEngine.onSpeak.addListener(speakListener);
+    chrome.ttsEngine.onStop.addListener(stopListener);
+
+    // This should go to our own TTS engine, and we can check that we
+    // get the error message.
+    chrome.tts.speak(
+        'extension speech',
+        {
+         'onevent': function(event) {
+           chrome.test.assertEq('error', event.type);
+           chrome.test.assertEq('extension tts error', event.errorMessage);
+           chrome.ttsEngine.onSpeak.removeListener(speakListener);
+           chrome.ttsEngine.onStop.removeListener(stopListener);
+           chrome.test.succeed();
+         }
+        },
+        function() {
+          chrome.test.assertNoLastError();
+        });
+  }
+]);"}<_**next**_>{"sha": "7d283570f4e27f4d8b5bb8b4c48affb46eb27e49", "filename": "chrome/test/data/extensions/api_test/tts_engine/engine_word_callbacks/manifest.json", "status": "added", "additions": 16, "deletions": 0, "changes": 16, "blob_url": "https://github.com/chromium/chromium/blob/c63f2b7fe4fe2977f858a8e36d5f48db17eff2e7/chrome/test/data/extensions/api_test/tts_engine/engine_word_callbacks/manifest.json", "raw_url": "https://github.com/chromium/chromium/raw/c63f2b7fe4fe2977f858a8e36d5f48db17eff2e7/chrome/test/data/extensions/api_test/tts_engine/engine_word_callbacks/manifest.json", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/chrome/test/data/extensions/api_test/tts_engine/engine_word_callbacks/manifest.json?ref=c63f2b7fe4fe2977f858a8e36d5f48db17eff2e7", "patch": "@@ -0,0 +1,16 @@
