+<script src="test.js"></script>"}<_**next**_>{"sha": "9a304ba8397527525f19a2dab4f7f067086e9be5", "filename": "chrome/test/data/extensions/api_test/tts_engine/engine_word_callbacks/test.js", "status": "added", "additions": 66, "deletions": 0, "changes": 66, "blob_url": "https://github.com/chromium/chromium/blob/c63f2b7fe4fe2977f858a8e36d5f48db17eff2e7/chrome/test/data/extensions/api_test/tts_engine/engine_word_callbacks/test.js", "raw_url": "https://github.com/chromium/chromium/raw/c63f2b7fe4fe2977f858a8e36d5f48db17eff2e7/chrome/test/data/extensions/api_test/tts_engine/engine_word_callbacks/test.js", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/chrome/test/data/extensions/api_test/tts_engine/engine_word_callbacks/test.js?ref=c63f2b7fe4fe2977f858a8e36d5f48db17eff2e7", "patch": "@@ -0,0 +1,66 @@
+// Copyright (c) 2011 The Chromium Authors. All rights reserved.
+// Use of this source code is governed by a BSD-style license that can be
+// found in the LICENSE file.
+
+// TTS api test for Chrome on ChromeOS.
+// browser_tests.exe --gtest_filter="TtsApiTest.*"
+
+if (!chrome.tts) {
+  chrome.tts = chrome.experimental.tts;
+}
+
+if (!chrome.ttsEngine) {
+  chrome.ttsEngine = chrome.experimental.ttsEngine;
+}
+
+chrome.test.runTests([
+  function testWordCallbacks() {
+    // Register listeners for speech functions, enabling this extension
+    // to be a TTS engine.
+    var speakListener = function(utterance, options, sendTtsEvent) {
+      chrome.test.assertNoLastError();
+      chrome.test.assertEq('alpha beta gamma', utterance);
+      sendTtsEvent({'type': 'word', 'charIndex': 0});
+      sendTtsEvent({'type': 'word', 'charIndex': 6});
+      sendTtsEvent({'type': 'word', 'charIndex': 11});
+      sendTtsEvent({'type': 'end', 'charIndex': utterance.length});
+    };
+    var stopListener = function() {};
+    chrome.ttsEngine.onSpeak.addListener(speakListener);
+    chrome.ttsEngine.onStop.addListener(stopListener);
+
+    var callbacks = 0;
+    chrome.tts.speak(
+        'alpha beta gamma',
+        {
+         'onevent': function(event) {
+           chrome.test.assertNoLastError();
+           callbacks++;
+           switch(callbacks) {
+           case 1:
+             chrome.test.assertEq('word', event.type);
+             chrome.test.assertEq(0, event.charIndex);
+             break;
+           case 2:
+             chrome.test.assertEq('word', event.type);
+             chrome.test.assertEq(6, event.charIndex);
+             break;
+           case 3:
+             chrome.test.assertEq('word', event.type);
+             chrome.test.assertEq(11, event.charIndex);
+             break;
+           case 4:
+             chrome.test.assertEq('end', event.type);
+             chrome.test.assertEq(16, event.charIndex);
+             chrome.test.succeed();
+             break;
+           default:
+             chrome.test.fail();
+           }
+         }
+        },
+        function() {
+          chrome.test.assertNoLastError();
+        });
+  }
+]);"}<_**next**_>{"sha": "77b5f03c87e010b91e65d29c2a386fc94779530f", "filename": "chrome/test/data/extensions/api_test/tts_engine/register_engine/manifest.json", "status": "added", "additions": 22, "deletions": 0, "changes": 22, "blob_url": "https://github.com/chromium/chromium/blob/c63f2b7fe4fe2977f858a8e36d5f48db17eff2e7/chrome/test/data/extensions/api_test/tts_engine/register_engine/manifest.json", "raw_url": "https://github.com/chromium/chromium/raw/c63f2b7fe4fe2977f858a8e36d5f48db17eff2e7/chrome/test/data/extensions/api_test/tts_engine/register_engine/manifest.json", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/chrome/test/data/extensions/api_test/tts_engine/register_engine/manifest.json?ref=c63f2b7fe4fe2977f858a8e36d5f48db17eff2e7", "patch": "@@ -0,0 +1,22 @@
