 break;

 case CHUNK_ART1:
                art1Pos = chunkPos + 8;
 break;

 case CHUNK_ART2:
                art2Pos = chunkPos + 8;
 break;

 default:
 break;

 }
 }

 if (art1Pos)
 {
 if ((result = Parse_art(pDLSData, art1Pos, pArt)) != EAS_SUCCESS)
 return result;
 }

 if (art2Pos)
 {
 if ((result = Parse_art(pDLSData, art2Pos, pArt)) != EAS_SUCCESS)
 return result;
 }

 return EAS_SUCCESS;
}

