+// Copyright (c) 2011 The Chromium Authors. All rights reserved.
+// Use of this source code is governed by a BSD-style license that can be
+// found in the LICENSE file.
+
+// TTS api test for Chrome on ChromeOS.
+// browser_tests.exe --gtest_filter="TtsApiTest.*"
+
+chrome.test.runTests([
+  function testWordCallbacks() {
+    var callbacks = 0;
+    chrome.experimental.tts.speak(
+        'one two three',
+        {
+         'onevent': function(event) {
+           callbacks++;
+           switch(callbacks) {
+           case 1:
+             chrome.test.assertEq('word', event.type);
+             chrome.test.assertEq(0, event.charIndex);
+             break;
+           case 2:
+             chrome.test.assertEq('word', event.type);
+             chrome.test.assertEq(4, event.charIndex);
+             break;
+           case 3:
+             chrome.test.assertEq('word', event.type);
+             chrome.test.assertEq(8, event.charIndex);
+             break;
+           case 4:
+             chrome.test.assertEq('end', event.type);
+             chrome.test.assertEq(13, event.charIndex);
+             chrome.test.succeed();
+             break;
+           default:
+             chrome.test.fail();
+           }
+         }
+        });
+  }
+]);"}<_**next**_>{"sha": "39ac6163d496fcfd6fb71e7953045bb39f4ed6f5", "filename": "chrome/test/data/extensions/api_test/tts_engine/engine_error/manifest.json", "status": "renamed", "additions": 4, "deletions": 8, "changes": 12, "blob_url": "https://github.com/chromium/chromium/blob/c63f2b7fe4fe2977f858a8e36d5f48db17eff2e7/chrome/test/data/extensions/api_test/tts_engine/engine_error/manifest.json", "raw_url": "https://github.com/chromium/chromium/raw/c63f2b7fe4fe2977f858a8e36d5f48db17eff2e7/chrome/test/data/extensions/api_test/tts_engine/engine_error/manifest.json", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/chrome/test/data/extensions/api_test/tts_engine/engine_error/manifest.json?ref=c63f2b7fe4fe2977f858a8e36d5f48db17eff2e7", "patch": "@@ -3,16 +3,12 @@
