+// META: script=/resources/testdriver-vendor.js
+// META: script=/bluetooth/resources/bluetooth-helpers.js
+'use strict';
+const test_desc = 'getAvailability() resolves with false if the system does ' +
+    'not have an adapter.';
+
+bluetooth_test(async () => {
+  await navigator.bluetooth.test.simulateCentral({state: 'absent'});
+  let availability = await navigator.bluetooth.getAvailability();
+  assert_false(
+      availability,
+      'getAvailability() resolves promise with false when adapter is absent.');
+}, test_desc);"}<_**next**_>{"sha": "d5e9d1f2b6ffbb009b03d0cde8155144aeee630b", "filename": "third_party/blink/web_tests/external/wpt/bluetooth/adapter/adapter-added-getAvailability.https.window.js", "status": "added", "additions": 24, "deletions": 0, "changes": 24, "blob_url": "https://github.com/chromium/chromium/blob/62154472bd2c43e1790dd1bd8a527c1db9118d88/third_party/blink/web_tests/external/wpt/bluetooth/adapter/adapter-added-getAvailability.https.window.js", "raw_url": "https://github.com/chromium/chromium/raw/62154472bd2c43e1790dd1bd8a527c1db9118d88/third_party/blink/web_tests/external/wpt/bluetooth/adapter/adapter-added-getAvailability.https.window.js", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/blink/web_tests/external/wpt/bluetooth/adapter/adapter-added-getAvailability.https.window.js?ref=62154472bd2c43e1790dd1bd8a527c1db9118d88", "patch": "@@ -0,0 +1,24 @@
+// META: script=/resources/testharness.js
+// META: script=/resources/testharnessreport.js
+// META: script=/resources/testdriver.js
+// META: script=/resources/testdriver-vendor.js
+// META: script=/bluetooth/resources/bluetooth-helpers.js
+'use strict';
+const test_desc = 'getAvailability() resolves with true after adapter is ' +
+    'inserted into a system with a platform that supports Bluetooth LE.';
+
+bluetooth_test(async () => {
+  const fake_central =
+      await navigator.bluetooth.test.simulateCentral({state: 'absent'});
+  let availability = await navigator.bluetooth.getAvailability();
+  assert_false(
+      availability,
+      'getAvailability() resolves promise with false when adapter is absent.');
+
+  await fake_central.setState('powered-on');
+  availability = await navigator.bluetooth.getAvailability();
+  assert_true(
+      availability,
+      'getAvailability() resolves promise with true after Bluetooth LE ' +
+          'capable adapter has been has been added.');
+}, test_desc);"}<_**next**_>{"sha": "8fe9265a46ed22a9bb0e0480f045135b323565f0", "filename": "third_party/blink/web_tests/external/wpt/bluetooth/adapter/adapter-powered-off-getAvailability.https.window.js", "status": "added", "additions": 17, "deletions": 0, "changes": 17, "blob_url": "https://github.com/chromium/chromium/blob/62154472bd2c43e1790dd1bd8a527c1db9118d88/third_party/blink/web_tests/external/wpt/bluetooth/adapter/adapter-powered-off-getAvailability.https.window.js", "raw_url": "https://github.com/chromium/chromium/raw/62154472bd2c43e1790dd1bd8a527c1db9118d88/third_party/blink/web_tests/external/wpt/bluetooth/adapter/adapter-powered-off-getAvailability.https.window.js", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/blink/web_tests/external/wpt/bluetooth/adapter/adapter-powered-off-getAvailability.https.window.js?ref=62154472bd2c43e1790dd1bd8a527c1db9118d88", "patch": "@@ -0,0 +1,17 @@
+// META: script=/resources/testharness.js
