+    assert_true(
+        availability,
+        'getAvailability() resolves promise with true after adapter powered ' +
+            'off.');
+  }
+
+  {
+    await fake_central.setState('powered-on');
+    const availability = await navigator.bluetooth.getAvailability();
+    assert_true(
+        availability,
+        'getAvailability() resolves promise with true when adapter is ' +
+            'powered back on.');
+  }
+}, test_desc);"}<_**next**_>{"sha": "cc2c33d1d4c2bf2cdad0cd0874a739b462ff90ec", "filename": "third_party/blink/web_tests/external/wpt/bluetooth/adapter/adapter-removed-getAvailability.https.window.js", "status": "added", "additions": 25, "deletions": 0, "changes": 25, "blob_url": "https://github.com/chromium/chromium/blob/62154472bd2c43e1790dd1bd8a527c1db9118d88/third_party/blink/web_tests/external/wpt/bluetooth/adapter/adapter-removed-getAvailability.https.window.js", "raw_url": "https://github.com/chromium/chromium/raw/62154472bd2c43e1790dd1bd8a527c1db9118d88/third_party/blink/web_tests/external/wpt/bluetooth/adapter/adapter-removed-getAvailability.https.window.js", "contents_url": "https://api.github.com/repos/chromium/chromium/contents/third_party/blink/web_tests/external/wpt/bluetooth/adapter/adapter-removed-getAvailability.https.window.js?ref=62154472bd2c43e1790dd1bd8a527c1db9118d88", "patch": "@@ -0,0 +1,25 @@
