 while (1) {

        n = read(omx->m_pipe_in, &id, 1);

 if (0 == n) {
 break;
 }

 if (1 == n) {
            omx->process_event_cb(omx, id);
 }
 if ((n < 0) && (errno != EINTR)) {
            DEBUG_PRINT_LOW("ERROR: read from pipe failed, ret %d errno %d", n, errno);
 break;
 }
 }
    DEBUG_PRINT_HIGH("omx_vdec: message thread stop");
 return 0;
}

