+			};
+		};
+	};
+};"}<_**next**_>{"sha": "4a99ee5a923faab980d675aab5d9234f8bf6f987", "filename": "arch/arm/dts/ste-dbx5x0-u-boot.dtsi", "status": "added", "additions": 29, "deletions": 0, "changes": 29, "blob_url": "https://github.com/u-boot/u-boot/blob/2c871f9e084b2c03d1961884228a6901387ab8d6/arch/arm/dts/ste-dbx5x0-u-boot.dtsi", "raw_url": "https://github.com/u-boot/u-boot/raw/2c871f9e084b2c03d1961884228a6901387ab8d6/arch/arm/dts/ste-dbx5x0-u-boot.dtsi", "contents_url": "https://api.github.com/repos/u-boot/u-boot/contents/arch/arm/dts/ste-dbx5x0-u-boot.dtsi?ref=2c871f9e084b2c03d1961884228a6901387ab8d6", "patch": "@@ -0,0 +1,29 @@
