-void AutofillPopupViewViews::Hide() {
-  // The controller is no longer valid after it hides us.
-  controller_ = NULL;
-  ui::AXPlatformNode::OnInputSuggestionsUnavailable();
-  DoHide();
-  NotifyAccessibilityEvent(ax::mojom::Event::kMenuEnd, true);
