-  DCHECK_EQ(controller_->GetLineCount(), child_count());
-  for (int i = 0; i < controller_->GetLineCount(); ++i) {
-    gfx::Rect line_rect = controller_->layout_model().GetRowBounds(i);
-
-    if (controller_->GetSuggestionAt(i).frontend_id ==
