-  SetSize(bounds.size());
-
-  gfx::Rect clipping_bounds = CalculateClippingBounds();
-
-  int available_vertical_space = clipping_bounds.height() -
-                                 (bounds.y() - clipping_bounds.y()) -
-                                 kPopupBottomMargin;
